import csv
import io
import re

_INT_RE = re.compile(r'^[+-]?\d+$')
_FLOAT_RE = re.compile(r'^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?$')


def _infer(value):
    if value in ('null', 'None', 'NULL'):
        return None
    if value in ('true', 'True'):
        return True
    if value in ('false', 'False'):
        return False
    if _INT_RE.match(value):
        # Preserve leading zeros (e.g. '007') as strings
        if len(value.lstrip('+-')) > 1 and value.lstrip('+-')[0] == '0':
            return value
        return int(value)
    if _FLOAT_RE.match(value):
        return float(value)
    return value


def parse_csv_typed(csv_string):
    reader = csv.reader(io.StringIO(csv_string))
    rows = [row for row in reader if row and any(field.strip() for field in row)]
    if not rows:
        return []
    header = [h.strip() for h in rows[0]]
    result = []
    for row in rows[1:]:
        result.append({header[i]: _infer(row[i]) for i in range(min(len(header), len(row)))})
    return result
